import test from 'node:test';
import assert from 'node:assert/strict';
import { canAccess, filterEvents, summarizeEvents, transitionEvent, appendReport } from '../src/data/domain.js';

const reporter={id:'u-r',role:'reporter',scope:'own',officeId:'MRO-IV',status:'active'};
const reviewer={id:'u-v',role:'reviewer',scope:'all',officeId:'MRO-IV',status:'active'};
const fixture={id:'e1',ownerId:'u-r',officeId:'MRO-IV',status:'submitted',date:'2026-11-01',type:'Collision',seriousness:'less_serious',lat:null,lon:null,positionQuality:'unknown',vessels:[{id:'v1'},{id:'v2'}],consequences:{fatalities:null,missing:0,injured:2,rescued:null},history:[]};
test('own reporter scope and suspension are enforced despite overlapping operations',()=>{assert.equal(canAccess(reporter,'report',fixture),true);assert.equal(canAccess({...reporter,id:'other'},'report',fixture),false);assert.equal(canAccess({...reporter,status:'suspended'},'report',fixture),false);assert.equal(canAccess(reporter,'review',fixture),true);});
test('one multi-vessel event does not multiply casualties and unknown remains counted',()=>{const s=summarizeEvents([fixture]);assert.equal(s.events,1);assert.equal(s.vesselInvolvements,2);assert.equal(s.injured,2);assert.equal(s.unknownFatalities,1);assert.equal(s.unlocated,1);});
test('seriousness is exact, zero coordinate valid and partial coordinates unlocated',()=>{const rows=[fixture,{...fixture,id:'e2',seriousness:'serious',positionQuality:'reported',lat:0,lon:120},{...fixture,id:'e3',seriousness:'very_serious',lat:12,lon:null}];assert.equal(filterEvents(rows,{seriousness:'serious'}).length,1);assert.equal(summarizeEvents(rows).located,1);assert.equal(summarizeEvents(rows).unlocated,2);});
test('unknown dates excluded from selected year and missing counts not coerced on input',()=>{assert.equal(filterEvents([{...fixture,date:null,dateUnknown:true}],{year:'2026'}).length,0);assert.equal(fixture.consequences.fatalities,null);});
test('overlapping review stays scoped and stamps correction/validation history',()=>{assert.throws(()=>transitionEvent(fixture,'validated',{...reporter,id:'other'}));const corrected=transitionEvent(fixture,'correction_requested',reviewer,'Clarify position');assert.equal(corrected.history[0].actorId,reviewer.id);assert.equal(corrected.status,'correction_requested');const resubmitted=transitionEvent(corrected,'resubmitted',reporter,'Updated');assert.equal(resubmitted.history.length,2);assert.equal(resubmitted.history[1].remarks,'Updated');});
test('report revisions retained independently without replacing issued report',()=>{const prior=[{id:'r1',eventId:'e1',type:'2',revision:1,status:'issued',fields:{missing:3}}];const next=appendReport(prior,{id:'r2',eventId:'e1',type:'2',status:'draft',fields:{missing:1}});assert.equal(next.length,2);assert.equal(next[0].fields.missing,3);assert.equal(next[1].revision,2);});

test('unknown position is not mapped even when stale numeric coordinates exist',()=>{const totals=summarizeEvents([{...fixture,lat:12,lon:120,positionQuality:'unknown'}]);assert.equal(totals.located,0);assert.equal(totals.unlocated,1)});
